"""Layer 15 MLP down_proj, component 5897 (p-82af68dd@100000).

What it does: it fires on code keywords that announce a new name, a type, variable,
function or class (`int`, `void`, `const`, `var`, `function`, `def`, `func`, `struct`,
`namespace`, `String`, ...). It is strongest when such a keyword opens a line or statement,
right after indentation, a line break, `;`, `{`, `}`, `(` or `:`.

Two kinds of word are scored differently:
- Code-only words (declaration keywords that never occur as English) fire anywhere, at
  about a third of their strength in the middle of a line.
- Words that are also English (`if`, `for`, `let`, `public`, `import`, ...) fire only when
  they open a statement; inside a sentence of prose they stay near zero.
A keyword that continues a longer word (the `int` of `point`) is ignored.

Everything else predicts 0. Its output promotes identifier and type names, which is what
these declaration keywords are followed by. This simple version captures the large
positive activations; the diffuse small values on punctuation and prose words are not modelled.
"""

READS = ()

# Declaration words that only occur as code, with their strength at a statement start.
CODE_WORDS = {
    "int": 3.0, "void": 3.0, "const": 3.0, "var": 3.0, "function": 3.0, "def": 2.8,
    "func": 2.8, "fn": 2.6, "struct": 2.8, "namespace": 3.4, "String": 2.2, "double": 2.4,
    "float": 2.2, "bool": 2.0, "char": 1.8, "long": 1.0, "object": 1.0, "class": 2.2,
}
# Control and declaration words that are also English, with their strength at a statement start.
AMBIGUOUS = {
    "if": 2.1, "foreach": 2.7, "switch": 3.0, "while": 0.9, "for": 1.2, "let": 2.0,
    "private": 1.2, "static": 1.0, "public": 0.9, "import": 0.9, "package": 0.7,
}
MIDLINE_FACTOR = 0.3  # a code-only word mid-line, relative to its statement-start value
# Characters that end a statement or open a block or list, so the next word starts an item.
BOUNDARY = set(";{}(:")


def opens_statement(prefix):
    """True if the newest token starts a line or a statement."""
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return True
    prev = prefix.token_strings[-2]
    if "\n" in prev or prev.strip() == "":
        return True
    return prev.rstrip()[-1:] in BOUNDARY


def continues_word(prefix):
    """True if the newest token carries on a word, like the `int` of `point`."""
    if len(prefix.token_strings) < 2:
        return False
    cur, prev = prefix.token_strings[-1], prefix.token_strings[-2]
    return not cur[:1].isspace() and prev[-1:].isalnum()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if continues_word(prefix):
        return carry, 0.0
    if word in CODE_WORDS:
        strength = CODE_WORDS[word]
        value = strength if opens_statement(prefix) else MIDLINE_FACTOR * strength
    elif word in AMBIGUOUS and opens_statement(prefix):
        value = AMBIGUOUS[word]
    else:
        value = 0.0
    return carry, float(value)

"""Contrast and cause-relation detector for layers.15.mlp.down_proj, component 5899.

In plain terms: this component is a weak, diffuse feature. Its output pushes the
next-token distribution toward contrast words ("instead", "rather", "not"). It
is positive where the current word opens a contrast or a cause/dependence
relation:
  - "not" that is not an auxiliary negation: strongest after a comma ("X, not Y"),
    weaker after "is", "and", "but" ("is not only"); verbal negation such as
    "does not" or "will not" does not fire;
  - "by", "to", "on", "of", ... right after a cause or dependence verb or
    adjective: "determined by", "attributed to", "due to", "focus on", "based on";
  - "rather" and "instead";
  - "more", "less" and "because", weakly.
It is negative on the words that follow "not" in "not only", "not just" ("only",
"just", "both", "merely", "even"). Everywhere else it sits at its typical value,
the component's mean, -0.08.

The values are rounded mean activations of those groups on 8192 training rows. Most of
the variance is not captured by any such rule: a linear model on the surrounding
words reaches about 1.5% of variance on held-out rows, and these rules about 0.3-0.4%.
"""

from collections.abc import Mapping

READS = ()

MEAN = -0.08  # the component's mean activation, the value everywhere else

RELATION_WORDS = {"by", "to", "on", "of", "with", "from", "for", "in", "about", "through", "at"}
CAUSE_WORDS = {
    "determined", "caused", "driven", "explained", "controlled", "influenced", "led",
    "attributed", "focus", "focused", "depends", "depend", "based", "relies", "rely",
    "dependent", "due", "prompted", "achieved", "powered", "linked", "related",
}
LIMITERS = {"only", "just", "merely", "even", "both"}  # words that follow "not" in "not only"
AUXILIARIES = {
    "do", "does", "did", "will", "would", "could", "should", "may", "might", "can",
    "shall", "must", "have", "has", "had", "if", "to", "or",
}


def word(prefix, back):
    """The lowercased word `back` tokens before the newest; '' across a document edge."""
    i = len(prefix.token_ids) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream: Mapping):
    cur, prev = word(prefix, 0), word(prefix, 1)
    if cur == "not":
        value = MEAN if prev in AUXILIARIES else (1.5 if prev == "," else 0.3)
    elif cur in RELATION_WORDS and prev in CAUSE_WORDS:
        value = 0.41
    elif cur in {"rather", "instead"}:
        value = 0.28
    elif cur in {"more", "less", "because"}:
        value = 0.22
    elif cur in LIMITERS:
        value = -0.4
    else:
        value = MEAN
    return carry, float(value)

"""Draft 4: sign-by-role rule, with common words (by word frequency) set apart from content words.

It reads the current token and the one before it. Positive values go to content words
(less common words, subword pieces, digits, determiners); negative values go to the
punctuation and linking words that end a sentence or start a new clause (sentence-final
stops, commas, 'and', 'or', 'but' ...), most strongly a clause-linking conjunction right
after a comma. Very common words (wordfreq Zipf >= 6, such as 'the' or 'of') sit near zero.
"""
import re

import wordfreq

READS = ()

CONJ = set("and or but as with so yet while because which that nor".split())
PREPS = set("of in to for from on at by into about over under between through".split())
DETS = set("the a an this these those its their his her our your some".split())
END = set(".!?。！？")


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    tok = raw.strip()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if "\n" in raw:
        value = 0.15
    elif not tok:
        value = 0.1
    elif tok in CONJ:
        value = -1.2 if prev == "," else -0.55
    elif tok in END:
        value = -0.4 if prev[-1:].isalnum() else 0.2
    elif tok == ",":
        value = -0.3
    elif tok in PREPS:
        value = -0.13
    elif tok in DETS:
        value = 0.14
    elif re.fullmatch(r"[A-Za-z]+", tok):
        if prev == ",":
            value = 0.0
        elif not raw.startswith(" "):
            value = 0.24
        elif wordfreq.zipf_frequency(tok.lower(), "en") >= 6:
            value = -0.1
        else:
            value = 0.35
    elif re.fullmatch(r"\d+", tok):
        value = 0.18
    else:
        value = 0.0
    return carry, value

"""Second piece of a split word: a strongly negative write when a word begins with a
one-letter fragment.

Qwen's tokenizer often splits a rare word or a name into pieces. This component reads
the piece that follows a short opening fragment and writes a large negative value
there, and is near zero everywhere else:

- The current token is letters with no leading space (a word's continuation), and the
  previous token is a single letter that starts the word:
  - with a leading space and a capital (' C' + 'ontrol'):  about -8  (strongest)
  - with a leading space, lowercase (' b' + 'ary'):        about -5
  - no space before the fragment, capital ('C' + 'ontrol', as in '(C'): about -4
  - no space before the fragment, lowercase: about 0.
  - punctuation before the fragment, as in '/s' + 'ocket': about -2 (lowercase) to -3 (capital)
- The previous token is a two-letter word-start with a leading space (' Ch' + 'ang'): about -1.5.
- The current token is a second digit of a number (the previous one is a digit, the one
  before is not): about -2.

Everything else is predicted as 0. The values are the group means measured on training
text, so the program explains about a third of the component's variance.
"""

import regex

READS: tuple = ()


def step(carry, prefix, upstream):
    ts = prefix.token_strings
    if len(ts) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    cur, prev = ts[-1], ts[-2]
    if regex.fullmatch(r"\p{L}+", cur):
        m = regex.fullmatch(r"([\s\p{P}\p{S}]*)(\p{L})", prev)
        if m:
            lead, upper = m.group(1), m.group(2).isupper()
            if lead.startswith(" "):
                return carry, (-7.7 if upper else -5.1)
            if lead:
                return carry, (-3.4 if upper else -2.1)
            return carry, (-4.2 if upper else -0.25)
        if regex.fullmatch(r" \p{L}{2}", prev):
            return carry, -1.5
    if regex.fullmatch(r"\d", cur) and regex.fullmatch(r"\d", prev):
        if len(ts) < 3 or not regex.fullmatch(r"\d", ts[-3]):
            return carry, -1.9
    return carry, 0.0

"""Enablement and reduction words, read in their clause (weak, diffuse).

Layer 15's MLP output component 5927 is quiet almost everywhere (activation
about -0.02 with spread 0.4). Its visible spikes come on words that say what a
thing enables, permits or makes possible ("allow", "allows", "enable", "permit",
"able", "possible") and, more weakly, on words that say what it reduces or
requires ("reduce", "avoid", "less", "without", "need", "require").

The spikes are biggest when the verb follows a non-person subject or a
connective ("this allows", "which will enable", "thus reduces", "can allow"),
and they are small after "you" ("you allow"). The program gives those words a
value by the word before them, and every other token a resting value near the
mean. It explains very little of the variance (about 0.002): most of the
component's activation is diffuse, token-independent noise.
"""

READS = ()

REST = -0.025
ENABLE = {"allow", "allows", "allowing", "allowed", "enable", "enables",
          "enabling", "enabled", "permit", "permits", "permitting", "able",
          "possible"}
REDUCE = {"reduce", "reduces", "reducing", "reduced", "avoid", "avoids",
          "avoiding", "less", "without", "smaller", "fewer", "need", "needs",
          "needed", "require", "requires", "required", "requiring",
          "necessary", "save", "saves", "lower"}
# words before the verb that make its subject a thing, or a modal or connective
THING_OR_MODAL = {"this", "that", "which", "it", "thus", "thereby", "would",
                  "will", "can", "should", "may", "could", "to", "has", "have",
                  "also", "and", ","}
PERSON = {"you", "your", "we", "our", "they", "them", "i", "me", "my", "us",
          "users", "user", "people"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    before = _word(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""
    if word in ENABLE:
        if before in THING_OR_MODAL:
            value = 1.2
        elif before in PERSON:
            value = 0.0
        else:
            value = 0.3
    elif word in REDUCE:
        value = 0.6 if before in THING_OR_MODAL else 0.1
    else:
        value = REST
    return carry, float(value)

"""Layer 15 MLP hidden unit 5928 (this component's activation), read as a line-break detector.

The component reads almost only that one MLP hidden unit (its input vector has weight 0.86 on
unit 5928, out of a norm of 1.17). Its activation is mostly quiet, with a dip at line breaks:

- a line break right after a colon, question mark or exclamation mark ("Steps:\\n", "?\\n\\n")
  dips hard, to about -1.5 on average (it is more negative inside chat-template turns);
- a bare line break with only spaces before it ("\\n", "\\n\\n", " \\n\\n") dips mildly, about -0.6;
- line breaks after code punctuation (";\\n", "}\\n", ")\\n") are near zero;
- every other token is near zero, with noise that no simple rule here captures.

So the program predicts those dips and 0 elsewhere. It uses only the newest token, so it
keeps no state.
"""

import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

CLAUSE_END_BREAK = re.compile(r"[:?!]\n")
"""A line break right after a colon, question mark or exclamation mark."""

CLAUSE_END_VALUE = -1.5
PLAIN_BREAK_VALUE = -0.6


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1]
    if "\n" not in token:
        return carry, 0.0
    if CLAUSE_END_BREAK.search(token):
        return carry, CLAUSE_END_VALUE
    if token.strip() == "":
        return carry, PLAIN_BREAK_VALUE
    return carry, 0.0


def main() -> None:
    """Print the rule's values for a few example tokens, for a reader to check by eye."""
    for token in [":\n", "?\n\n", "\n\n", " \n", ";\n", "}\n", "the", ","]:
        value = CLAUSE_END_VALUE if CLAUSE_END_BREAK.search(token) else (
            PLAIN_BREAK_VALUE if "\n" in token and token.strip() == "" else 0.0
        )
        print(repr(token), value)


if __name__ == "__main__":
    main()

"""Candidate 2: the component's activation as a small table of token-kind means.

Component 5938 of layers.15.mlp.down_proj writes into the residual stream with a
mostly small, slightly negative value. Its large negative values come from tokens
that open a new unit of text: comment markers, quote or bracket openers, and the
blank line right after a think tag. Each kind of token gets the average activation
measured on training text; everything else gets a small default.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

THINK_TAGS = {"<think>", "</think>"}
GROUP_VALUES = {
    "think_break": -8.0,  # blank line right after <think> or </think>
    "comment": -2.5,  # // # ## ### /* -- : comment and heading markers
    "quote": -1.3,  # " ' ("  ('  {"  ="  \" : quote and bracket openers
    "markup": -1.0,  # ' *' ' `' ' |' '•' ' {' <|endoftext|>
    "sentence": -0.3,  # . ! ... and spaces, newlines, ')'
    "blank_line": -0.4,  # other blank lines
    "other": -0.1,  # everything else
}
COMMENT = {"//", " //", "#", " #", "##", "###", "///", "/*", "--"}
QUOTE = {'"', ' "', "'", " '", '("', "('", '{"', ' {"', '="', '(\\"', ' \\"', '\\"'}
MARKUP = {" *", " `", "`", " |", "•", " {\n", "<|endoftext|>"}
SENTENCE = {".", "!", "...", " ", "\n", ")"}


def kind(prev: str, tok: str) -> str:
    if tok == "\n\n" and prev in THINK_TAGS:
        return "think_break"
    if tok in COMMENT:
        return "comment"
    if tok in QUOTE:
        return "quote"
    if tok in MARKUP:
        return "markup"
    if tok in SENTENCE:
        return "sentence"
    if tok == "\n\n":
        return "blank_line"
    return "other"


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if len(prefix.document_ids) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    return carry, GROUP_VALUES[kind(prev, tok)]

"""Layer 15 MLP unit 5944 (component 5944 of layers.15.mlp.down_proj), as a word-level rule.

This component reads mainly one hidden unit of the layer-15 MLP (unit 5944, about two thirds
of its input direction), with smaller contributions from other units. Its output pushes the
next-token distribution toward code closers such as `();`, `";` and `;`.

Read from the newest token alone, it responds to:
  - output and logging calls (print, printf, println, cout, echo, console.log, assert, ...):
    the strongest responses;
  - a method name attached to a dot in code (`.add`, `.push`, `.Printf`, `.save`, ...);
  - assignment operators (` =`, ` +=`, ` :=`) and `return`;
  - it is pushed slightly negative on string, brace and statement punctuation (`"`, `":`,
    `{`, `;`, `=>`, `://`).
Everything else is predicted as 0.

It explains only a small part of the variance on held-out text (about 5 to 6%): the neuron also
has many spikes that depend on context, which a word list cannot see.
"""

from collections.abc import Mapping
import re

READS: tuple[str, ...] = ()

# Output and logging calls: the strongest responses.
OUTPUT_CALLS = {
    "print", "printf", "println", "puts", "echo", "cout", "console", "log", "fmt",
    "assert", "write", "writeline", "display", "warn", "info", "debug", "printstacktrace",
}

# Assignments and return: moderate responses.
ASSIGNMENT_OPS = {"=", "+=", ":=", "-=", "|="}

# String, brace and statement punctuation of code and URLs: slightly negative.
PUNCTUATION = {'"', '":', "{", ";", "=>", "://", '"/'}

DOTTED_NAME = re.compile(r"\.[A-Za-z_]\w*")

VALUE = {"output": 5.0, "method": 1.7, "assign": 1.5, "return": 2.8, "punct": -0.4}


def step(carry, prefix, upstream: Mapping):
    """The activation at this position, from the newest token alone."""
    raw = prefix.token_strings[-1]
    token = raw.strip()
    if token.lstrip(".").lower() in OUTPUT_CALLS:
        return carry, VALUE["output"]
    if DOTTED_NAME.fullmatch(raw.strip()):
        return carry, VALUE["method"]
    if token in ASSIGNMENT_OPS:
        return carry, VALUE["assign"]
    if token == "return":
        return carry, VALUE["return"]
    if token in PUNCTUATION:
        return carry, VALUE["punct"]
    return carry, 0.0
